// @ts-check

import { getRequire } from '../../../utils/Runtime.js'
import { UtilsConst } from '../../../utils/UtilsConst.js'

const requireDynamic = getRequire(import.meta.url)
const https = requireDynamic('https')
const os = requireDynamic('os')

const FALLBACK_ADDRESS = 'https://polandcentral-0.in.applicationinsights.azure.com/v2/track'
const DEFAULT_INSTRUMENTATION_KEY = '87e949af-cf27-489c-8518-591b3b55b667'
const APPINSIGHTS_CONNECTION_STRING_ENV_NAME = 'HYPERTUBE_APPLICATIONINSIGHTS_CONNECTION_STRING'
const CALLING_RUNTIME_NAME = 'Nodejs'
const REQUEST_TIMEOUT_MS = 3000
const VERSION = getPackageVersion()

/**
 * @typedef {Object} TelemetryTarget
 * @property {string} address
 * @property {string} instrumentationKey
 */

function getPackageVersion() {
    try {
        return requireDynamic('../../../../package.json').version ?? 'Unknown'
    } catch {
        return 'Unknown'
    }
}

class MessageHelper {
    /** @type {MessageHelper | null} */
    static #instance = null

    static getInstance() {
        if (MessageHelper.#instance === null) {
            MessageHelper.#instance = new MessageHelper()
        }
        return MessageHelper.#instance
    }

    /**
     * Starts sending a telemetry message to Application Insights without blocking the caller.
     * Telemetry failures are intentionally swallowed so they cannot affect SDK operations.
     * @param {string} operationName
     * @param {string} message
     * @returns {void}
     */
    sendMessageToAppInsights(operationName, message) {
        void this.sendMessageToAppInsightsAsync(operationName, message).catch(() => {})
    }

    /**
     * Async telemetry transport exposed for internal use and tests.
     * @param {string} operationName
     * @param {string} message
     * @returns {Promise<number>} The HTTP status code, or -1 when the request fails.
     */
    sendMessageToAppInsightsAsync(operationName, message) {
        const licenseKey = UtilsConst.getLicenseKey()

        const isBinaryException =
            message.includes('BinariesUnloader exception') || message.includes('BinariesExtractor exception')
        if (isBinaryException && licenseKey === 'functional-tests-key') {
            return Promise.resolve(0)
        }

        return new Promise((resolve) => {
            try {
                const telemetryTarget = this.#resolveTelemetryTarget()
                const nodeName = this.#getHostName()
                const payload = JSON.stringify({
                    name: 'AppEvents',
                    time: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
                    iKey: telemetryTarget.instrumentationKey,
                    tags: {
                        'ai.application.ver': VERSION,
                        'ai.cloud.roleInstance': nodeName,
                        'ai.operation.id': '0',
                        'ai.operation.parentId': '0',
                        'ai.operation.name': operationName,
                        'ai.internal.sdkVersion': 'hypertube',
                        'ai.internal.nodeName': nodeName,
                    },
                    data: {
                        baseType: 'EventData',
                        baseData: {
                            ver: 2,
                            name: message,
                            properties: {
                                OperatingSystem: `${os.platform()} ${os.arch()}`,
                                LicenseKey: licenseKey,
                                CallingTechnology: CALLING_RUNTIME_NAME,
                            },
                        },
                    },
                })

                const request = https.request(
                    telemetryTarget.address,
                    {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Content-Length': Buffer.byteLength(payload),
                        },
                        timeout: REQUEST_TIMEOUT_MS,
                    },
                    (/** @type {import('http').IncomingMessage} */ response) => {
                        response.resume?.()
                        resolve(response.statusCode ?? -1)
                    }
                )

                request.on('error', () => resolve(-1))
                request.on('timeout', () => {
                    resolve(-1)
                    request.destroy()
                })
                request.end(payload)
            } catch {
                resolve(-1)
            }
        })
    }

    #getHostName() {
        try {
            return os.hostname()
        } catch {
            return 'Unknown Host'
        }
    }

    /**
     * @returns {TelemetryTarget}
     */
    #resolveTelemetryTarget() {
        const rawConnectionString = process.env[APPINSIGHTS_CONNECTION_STRING_ENV_NAME]
        if (!rawConnectionString || rawConnectionString.trim().length === 0) {
            return {
                address: FALLBACK_ADDRESS,
                instrumentationKey: DEFAULT_INSTRUMENTATION_KEY,
            }
        }

        const values = this.#parseConnectionString(rawConnectionString)
        const ingestionEndpoint = values.ingestionendpoint
        const instrumentationKey = values.instrumentationkey

        const address = ingestionEndpoint
            ? `${ingestionEndpoint.replace(/\/+$/, '')}/v2/track`
            : FALLBACK_ADDRESS
        return {
            address,
            instrumentationKey: instrumentationKey || DEFAULT_INSTRUMENTATION_KEY,
        }
    }

    /**
     * @param {string} rawConnectionString
     * @returns {Record<string, string>}
     */
    #parseConnectionString(rawConnectionString) {
        /** @type {Record<string, string>} */
        const result = {}
        for (const segmentRaw of rawConnectionString.split(';')) {
            const segment = segmentRaw.trim()
            if (!segment) {
                continue
            }

            const separatorIndex = segment.indexOf('=')
            if (separatorIndex <= 0 || separatorIndex >= segment.length - 1) {
                continue
            }

            const key = segment.slice(0, separatorIndex).trim().toLowerCase()
            const value = segment.slice(separatorIndex + 1).trim()
            if (!key || !value) {
                continue
            }

            result[key] = value
        }
        return result
    }
}

/**
 * Sends a telemetry message using the shared helper instance.
 * @param {string} operationName
 * @param {string} message
 * @returns {void}
 */
function sendMessageToAppInsights(operationName, message) {
    MessageHelper.getInstance().sendMessageToAppInsights(operationName, message)
}

export { MessageHelper, sendMessageToAppInsights }
